item.command:
/bin/zsh -lc "cat > outputs/app/tokens.css <<'EOF'
:root {
  color-scheme: light;
  --scene: #e9eceb;
  --bg: #fafbf9;
  --surface: #f0f2ef;
  --field: #ffffff;
  --fg: #242c29;
  --muted: #606b65;
  --line: #dce1dc;
  --line-strong: #7b8780;
  --accent: #245b46;
  --accent-hover: #194a37;
  --on-accent: #ffffff;
  --health: #276346;
  --health-bg: #eaf2eb;
  --caution: #775014;
  --caution-bg: #f7f0df;
  --focus: #2967a5;
  --shadow: 0 14px 40px #17231c24, 0 2px 7px #17231c12;
  --font: -apple-system, BlinkMacSystemFont, 'Helvetica Neue', sans-serif;
  --mono: 'Rota Mono', ui-monospace, monospace;
  --fs-xs: 11px;
  --fs-sm: 12px;
  --fs-body: 13px;
  --fs-md: 14px;
  --fs-lg: 16px;
  --fs-title: 23px;
  --line-body: 1.45;
  --line-title: 1.2;
  --weight-normal: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --weight-bold: 700;
  --tracking: -0.45px;
  --caps-tracking: 0.75px;
  --s0: 0px;
  --s1: 4px;
  --s2: 8px;
  --s3: 12px;
  --s4: 16px;
  --s5: 20px;
  --s6: 24px;
  --s7: 28px;
  --s8: 32px;
  --s9: 40px;
  --s10: 48px;
  --s11: 56px;
  --radius-sm: 6px;
  --radius-md: 9px;
  --radius-lg: 13px;
  --radius-round: 50%;
  --border: 1px;
  --focus-width: 2px;
  --focus-offset: 3px;
  --popover-width: 360px;
  --popover-max: 640px;
  --scene-inset: 20px;
  --progress: 33.333%;
  --textarea-height: 86px;
  --duration: 120ms;
  --ease: ease-out;
}
:root[data-theme=\"dark\"] {
  color-scheme: dark;
  --scene: #171c19;
  --bg: #252b27;
  --surface: #2e3530;
  --field: #202622;
  --fg: #edf0eb;
  --muted: #b0b9b1;
  --line: #3c453e;
  --line-strong: #849187;
  --accent: #acd6b9;
  --accent-hover: #c0e4ca;
  --on-accent: #183a28;
  --health: #b0d7bc;
  --health-bg: #2b3c30;
  --caution: #e5c188;
  --caution-bg: #3c3425;
  --focus: #8fbef1;
  --shadow: 0 14px 40px #00000050, 0 2px 7px #00000030;
}
EOF
cat > outputs/app/style.css <<'EOF'
@font-face { font-family: 'Rota Mono'; src: url('plex-mono-400-latin.woff2') format('woff2'); font-weight: 400; font-display: swap; }
* { box-sizing: border-box; }
body { margin: var(--s0); background: var(--scene); color: var(--fg); font: var(--weight-normal) var(--fs-body)/var(--line-body) var(--font); -webkit-font-smoothing: antialiased; }
button, input, textarea { font: inherit; }
button { cursor: pointer; }
button, a, input, textarea { -webkit-tap-highlight-color: transparent; }
button:focus-visible, a:focus-visible, input:focus-visible, textarea:focus-visible { outline: var(--focus-width) solid var(--focus); outline-offset: var(--focus-offset); }
button:disabled { cursor: default; }
#app { width: var(--popover-width); max-height: var(--popover-max); margin: var(--scene-inset); overflow: auto; background: var(--bg); border: var(--border) solid var(--line-strong); border-radius: var(--radius-lg); box-shadow: var(--shadow); }
.app-header { height: var(--s11); display: flex; align-items: center; justify-content: space-between; padding: var(--s0) var(--s5); border-bottom: var(--border) solid var(--line); }
.brand { display: flex; align-items: center; gap: var(--s2); font-size: var(--fs-lg); font-weight: var(--weight-semibold); letter-spacing: var(--tracking); }
.icon { width: var(--s4); height: var(--s4); flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.brand .icon { width: var(--s5); height: var(--s5); }
.team-label { color: var(--muted); font-size: var(--fs-sm); }
.content { padding: var(--s5); }
.date-line { display: flex; align-items: center; justify-content: space-between; color: var(--muted); font-size: var(--fs-sm); margin-bottom: var(--s5); }
.mono { font-family: var(--mono); font-size: var(--fs-xs); font-variant-numeric: tabular-nums; }
h1, h2, p { margin: var(--s0); }
h1 { font-size: var(--fs-title); line-height: var(--line-title); letter-spacing: var(--tracking); font-weight: var(--weight-semibold); }
h2 { font-size: var(--fs-body); font-weight: var(--weight-semibold); }
.muted { color: var(--muted); }
.shift { padding: var(--s4); border: var(--border) solid var(--line); border-radius: var(--radius-md); background: var(--surface); }
.status { display: flex; gap: var(--s2); align-items: center; color: var(--health); font-size: var(--fs-sm); font-weight: var(--weight-medium); margin-bottom: var(--s2); }
.dot { height: var(--s2); width: var(--s2); background: currentColor; border-radius: var(--radius-round); flex: none; }
.shift h1 { font-size: var(--fs-title); margin-bottom: var(--s1); }
.owner { color: var(--muted); font-size: var(--fs-sm); }
.shift-time { display: flex; justify-content: space-between; margin-top: var(--s5); font-variant-numeric: tabular-nums; font-size: var(--fs-sm); }
.progress { height: var(--s1); background: var(--line); border-radius: var(--radius-sm); margin: var(--s2) var(--s0); overflow: hidden; }
.progress span { display: block; height: 100%; width: var(--progress); background: var(--health); }
.remaining { color: var(--muted); font-size: var(--fs-sm); }
.primary, .secondary { width: 100%; min-height: var(--s9); display: flex; align-items: center; justify-content: center; gap: var(--s2); padding: var(--s2) var(--s3); border-radius: var(--radius-sm); font-weight: var(--weight-medium); border: var(--border) solid transparent; transition: background var(--duration) var(--ease); }
.primary { background: var(--accent); color: var(--on-accent); }
.primary:hover { background: var(--accent-hover); }
.primary:disabled { color: var(--muted); background: var(--line); }
.shift .primary { margin-top: var(--s4); }
.secondary { background: var(--surface); color: var(--fg); border-color: var(--line); }
.secondary:hover { background: var(--line); }
.text-button { min-height: var(--s8); padding: var(--s1) var(--s2); margin-right: calc(-1 * var(--s2)); color: var(--muted); background: transparent; border: none; border-radius: var(--radius-sm); font-size: var(--fs-sm); }
.text-button:hover { color: var(--fg); background: var(--surface); }
.roster { margin-top: var(--s6); }
.section-heading { display: flex; align-items: baseline; justify-content: space-between; }
.section-heading span { color: var(--muted); font-size: var(--fs-xs); }
.people { list-style: none; padding: var(--s0); margin: var(--s2) var(--s0) var(--s0); }
.person { display: flex; align-items: center; gap: var(--s3); min-height: var(--s11); border-bottom: var(--border) solid var(--line); }
.person:last-child { border-bottom: none; }
.avatar { width: var(--s8); height: var(--s8); background: var(--surface); border: var(--border) solid var(--line); border-radius: var(--radius-round); display: flex; align-items: center; justify-content: center; font-size: var(--fs-xs); color: var(--muted); flex: none; }
.person-info { flex: 1; }
.person-name { font-weight: var(--weight-medium); }
.person-role { font-size: var(--fs-sm); color: var(--muted); }
.person time { color: var(--muted); font-size: var(--fs-xs); font-family: var(--mono); }
.app-footer { padding: var(--s3) var(--s5); border-top: var(--border) solid var(--line); display: flex; align-items: center; justify-content: space-between; gap: var(--s2); font-size: var(--fs-xs); color: var(--muted); }
.app-footer .icon { width: var(--s3); height: var(--s3); }
.footer-note { display: flex; align-items: center; gap: var(--s2); }
.page-intro { margin-bottom: var(--s6); }
.eyebrow { color: var(--muted); font-size: var(--fs-xs); text-transform: uppercase; letter-spacing: var(--caps-tracking); font-weight: var(--weight-semibold); margin-bottom: var(--s2); }
.page-intro h1 { margin-bottom: var(--s2); }
.page-intro p { color: var(--muted); font-size: var(--fs-sm); line-height: var(--line-body); }
.shift-summary { border-top: var(--border) solid var(--line); border-bottom: var(--border) solid var(--line); padding: var(--s3) var(--s0); margin-bottom: var(--s5); }
.shift-summary b { display: block; font-weight: var(--weight-medium); }
.shift-summary span { color: var(--muted); font-size: var(--fs-sm); }
fieldset { border: none; margin: var(--s0); padding: var(--s0); }
legend, .field-label { display: block; margin-bottom: var(--s2); font-weight: var(--weight-medium); }
.recipient { position: relative; display: flex; gap: var(--s3); align-items: center; padding: var(--s3); min-height: var(--s10); background: var(--field); border: var(--border) solid var(--line-strong); border-radius: var(--radius-md); cursor: pointer; }
.recipient:has(input:checked) { border-color: var(--accent); background: var(--health-bg); }
.recipient input { width: var(--s4); height: var(--s4); accent-color: var(--accent); margin: var(--s0) var(--s0) var(--s0) auto; order: 2; }
.recipient .avatar { background: var(--surface); }
.field { margin-top: var(--s5); }
.optional { color: var(--muted); font-weight: var(--weight-normal); font-size: var(--fs-sm); }
textarea { width: 100%; min-height: var(--textarea-height); resize: vertical; padding: var(--s3); background: var(--field); color: var(--fg); border: var(--border) solid var(--line-strong); border-radius: var(--radius-sm); }
textarea::placeholder { color: var(--muted); }
.responsibility { display: flex; gap: var(--s2); align-items: flex-start; margin-top: var(--s4); color: var(--muted); font-size: var(--fs-sm); }
.responsibility .icon { margin-top: var(--s1); }
.actions { margin-top: var(--s5); display: grid; gap: var(--s2); }
.transfer { padding: var(--s4); background: var(--surface); border: var(--border) solid var(--line); border-radius: var(--radius-md); }
.transfer-person { display: flex; gap: var(--s3); align-items: center; }
.transfer-person .avatar { background: var(--bg); }
.transfer-person small { display: block; color: var(--muted); font-size: var(--fs-xs); margin-bottom: var(--s1); }
.transfer-path { margin: var(--s2) var(--s0) var(--s2) var(--s4); height: var(--s4); border-left: var(--border) dashed var(--line-strong); }
.transfer-time { border-top: var(--border) solid var(--line); margin-top: var(--s4); padding-top: var(--s3); font-size: var(--fs-sm); color: var(--muted); }
.note-preview { margin-top: var(--s4); font-size: var(--fs-sm); overflow-wrap: anywhere; white-space: pre-wrap; }
.note-preview b { display: block; margin-bottom: var(--s1); }
.notice { padding: var(--s3); background: var(--caution-bg); color: var(--caution); border-radius: var(--radius-sm); font-size: var(--fs-sm); margin-bottom: var(--s5); }
.notice b { display: block; margin-bottom: var(--s1); font-weight: var(--weight-semibold); }
.notice p { line-height: var(--line-body); }
.state-symbol { display: flex; align-items: center; justify-content: center; width: var(--s10); height: var(--s10); color: var(--caution); background: var(--caution-bg); border-radius: var(--radius-round); margin-bottom: var(--s5); }
.state-symbol .icon { width: var(--s6); height: var(--s6); }
.state-symbol.success { color: var(--health); background: var(--health-bg); }
.pending-responsibility { margin-top: var(--s5); margin-bottom: var(--s0); }
.offline .status { color: var(--muted); }
.offline .content { padding-top: var(--s4); }
.offline .notice { margin-bottom: var(--s4); }
.offline .shift-time { margin-top: var(--s3); }
.offline .roster { margin-top: var(--s5); }
.offline .person { min-height: var(--s10); }
.offline .shift .primary { margin-top: var(--s3); }
.offline .remaining { margin-top: var(--s2); }
.empty-content { padding-top: var(--s8); padding-bottom: var(--s8); }
.empty-content h1 { margin-bottom: var(--s3); }
.empty-content p { color: var(--muted); margin-bottom: var(--s5); }
.empty-content .state-symbol { color: var(--muted); background: var(--surface); }
.inline-status { color: var(--health); background: var(--health-bg); border-radius: var(--radius-sm); padding: var(--s3); font-size: var(--fs-sm); margin-bottom: var(--s4); }
.screen-status:empty { display: none; }
.screen-status { font-size: var(--fs-sm); color: var(--muted); margin-top: var(--s3); }
:where(h1):focus { outline: none; }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none "'!important; animation: none !important; scroll-behavior: auto !important; } }
EOF
cp fixtures.js outputs/app/fixtures.js
cp fonts/plex-mono-400-latin.woff2 outputs/app/
cat > outputs/app/index.html <<'"'EOF'
<"'!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light dark">
<title>Rota — On call</title>
<link rel="stylesheet" href="tokens.css">
<link rel="stylesheet" href="style.css">
<script src="fixtures.js" defer></script>
<script src="app.js" defer></script>
</head>
<body><main id="app" aria-label="Rota on-call schedule"></main></body>
</html>
EOF
cat > outputs/app/app.js <<'"'EOF'
(() => {
  'use strict';
  const F = window.EVAL_FIXTURES;
  const M = F.menu;
  const app = document.querySelector('#app');
  const params = new URLSearchParams(location.search);
  const states = ['main', 'compose', 'review', 'pending', 'offline', 'empty', 'accepted'];
  let screen = states.includes(params.get('screen')) ? params.get('screen') : 'main';
  let selected = false;
  let note = '';
  let flash = '';
  let owner = params.get('owner') === 'priya' || screen === 'accepted' ? 'priya' : 'jamie';
  let pending = screen === 'pending' || params.get('request') === 'pending';
  const darkPreference = matchMedia('(prefers-color-scheme: dark)');
  const applyTheme = () => document.documentElement.dataset.theme = ['light','dark'].includes(params.get('theme')) ? params.get('theme') : darkPreference.matches ? 'dark' : 'light';
  applyTheme();
  darkPreference.addEventListener('change', applyTheme);
  const escapeHTML = value => String(value).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));
  const initials = name => name.split(' ').map(x=>x[0]).join('');
  const paths = {
    rota: '<path d=\"M5 5h9l-3-3M15 15H6l3 3M16 6v4M4 14v-4\"/>',
    arrow: '<path d=\"M3 8h10M9 4l4 4-4 4\"/>',
    clock: '<circle cx=\"8\" cy=\"8\" r=\"6\"/><path d=\"M8 4v4l3 2\"/>',
    check: '<path d=\"m3 8 3 3 7-7\"/>',
    wait: '<circle cx=\"8\" cy=\"8\" r=\"6\" stroke-dasharray=\"2.5 3\"/><path d=\"M8 4v4l2 1\"/>',
    offline: '<path d=\"m2 2 12 12M2 6a10 10 0 0 1 2-1M7 4a10 10 0 0 1 7 2M4 9a6 6 0 0 1 2-1M10 8l2 1M7 12l1-1 1 1\"/>',
    calendar: '<rect x=\"2\" y=\"3\" width=\"12\" height=\"11\" rx=\"2\"/><path d=\"M5 1v4M11 1v4M2 7h12M6 10h4\"/>',
    back: '<path d=\"m10 3-5 5 5 5\"/>'
  };
  const icon = name => "'`<svg class="icon" viewBox="0 0 16 16" aria-hidden="true">${paths[name] || '"''}</svg>"'`;
  const button = (text, action, type='"'primary', disabled=false) => "'`<button type="button" class="${type}" data-action="${action}" ${disabled ? '"'disabled' : ''}>"'${text}</button>`;
  const header = (action='"'') => "'`<header class="app-header"><div class="brand">${icon('"'rota')}<span>"'${escapeHTML(M.product)}</span></div>${action || '"'<span class=\"team-label\">Platform · '+M.teamSize+' people</span>'}</header>"'`;
  const asOf = new Date(F.now).toISOString().slice(11,16);
  const date = new Date(F.now).toLocaleDateString('"'en-GB',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'});
  const footer = (offline=false) => "'`<footer class="app-footer"><span class="footer-note">${icon(offline?'"'offline':'clock')}"'${offline?'"'Last known':'Schedule as of'} "'${asOf} UTC</span><span>18 Oct</span></footer>`;
  const person = p => `<li class="person"><span class="avatar" aria-hidden="true">${initials(p.name)}</span><div class="person-info"><div class="person-name">${escapeHTML(p.name)}</div><div class="person-role">${escapeHTML(p.role)}</div></div><time>${p.until}</time></li>`;
  const roster = () => `<section class="roster" aria-labelledby="roster-title"><div class="section-heading"><h2 id="roster-title">Also on call</h2><span>Until · UTC</span></div><ul class="people">${M.roster.filter(p=>p.name !== M.user).map(person).join('"'')}</ul></section>"'`;
  const responsibility = text => `<p class="responsibility">${icon('"'clock')}<span>"'${text}</span></p>`;
  function transfer() {
    return `<section class="transfer" aria-label="Handover details"><div class="transfer-person"><span class="avatar" aria-hidden="true">JE</span><div><small>From</small><b>${M.user} <span class="optional">(you)</span></b></div></div><div class="transfer-path" aria-hidden="true"></div><div class="transfer-person"><span class="avatar" aria-hidden="true">PR</span><div><small>To</small><b>${M.handoverTo}</b></div></div><div class="transfer-time">${M.rotation}<br>Remainder of today’s shift · until ${M.shiftEnd} UTC</div>${note?`<div class="note-preview"><b>Your note</b>${escapeHTML(note)}</div>`:'"''}</section>"'`;
  }
  function mainView(offline=false) {
    const transferred = owner === '"'priya';
    let status = offline ? 'Last known: you were on call' : transferred ? 'Priya is on call' : 'You’re on call';
    return "'`${header()}<div class="content"><div class="date-line"><span>${date}</span><span class="mono">UTC</span></div>${offline?'"'<aside class=\"notice\"><b>You’re offline</b><p>This schedule was saved at '+asOf+' UTC. Coverage may have changed.</p></aside>':''}"'${flash?`<p class="inline-status" role="status">${flash}</p>`:'"''}<section class=\"shift\" aria-labelledby=\"shift-title\"><div class=\"status\"><span class=\"dot\" aria-hidden=\"true\"></span>"'${status}</div><h1 id="shift-title" tabindex="-1">${M.rotation}</h1><p class="owner">${transferred ? M.handoverTo : M.user+'"' (you)'}</p><div class=\"shift-time\"><span>"'${M.shiftStart}</span><span>${M.shiftEnd} UTC</span></div>${offline?'"'':"'`<div class="progress" role="progressbar" aria-label="Shift progress at ${asOf} UTC" aria-valuemin="0" aria-valuemax="12" aria-valuenow="4"><span></span></div>`}<p class="remaining">${offline?'"'Current responsibility cannot be confirmed.':transferred?'Your handover is complete.':'8 hours remaining'}</p>"'${offline?button('"'Hand over shift','compose','primary',true)+responsibility('Reconnect before handing over.'):transferred?'':pending?button('View pending handover '+icon('arrow'),'pending'):button('Hand over shift '+icon('arrow'),'compose')}</section>"'${roster()}${offline?`<div class="actions">${button('"'Try again','retry','secondary')}</div><p class=\"screen-status\" role=\"status\" id=\"retry-status\"></p>"'`:'"''}</div>"'${footer(offline)}`;
  }
  function composeView() {
    return `${header(button('"'Cancel','cancel','text-button'))}<div class=\"content\"><div class=\"page-intro\"><div class=\"eyebrow\">Handover · 1 of 2</div><h1 tabindex=\"-1\">Hand over shift</h1><p>Ask a teammate to take the rest of your shift.</p></div><div class=\"shift-summary\"><b>"'${M.rotation}</b><span>Today · ${M.shiftStart}–${M.shiftEnd} UTC</span></div><form id="handover-form"><fieldset><legend>Hand over to</legend><label class="recipient"><span class="avatar" aria-hidden="true">PR</span><span><span class="person-name">${M.handoverTo}</span><br><span class="optional">Suggested teammate</span></span><input type="radio" name="recipient" value="priya" aria-label="${M.handoverTo}" ${selected?'"'checked':''} required></label></fieldset><div class=\"field\"><label class=\"field-label\" for=\"note\">Handover note <span class=\"optional\">(optional)</span></label><textarea id=\"note\" name=\"note\" maxlength=\"500\" placeholder=\"Anything Priya should know?\">"'${escapeHTML(note)}</textarea></div>${responsibility('"'You stay on call until Priya accepts.')}<div class=\"actions\"><button class=\"primary\" id=\"review-button\" type=\"submit\" "'${selected?'"'':'disabled'}>Review handover "'${icon('"'arrow')}</button></div></form></div>"'${footer()}`;
  }
  function reviewView() {
    return `${header(button(icon('"'back')+' Back','compose','text-button'))}<div class=\"content\"><div class=\"page-intro\"><div class=\"eyebrow\">Handover · 2 of 2</div><h1 tabindex=\"-1\">Review handover</h1><p>Check the details before sending your request.</p></div>"'${transfer()}${responsibility('"'Sending a request does not end your responsibility. You stay on call until Priya accepts.')}<div class=\"actions\">"'${button('"'Send handover request','send')}"'${button('"'Cancel','cancel','text-button')}</div></div>"'${footer()}`;
  }
  function pendingView() {
    return `${header()}<div class="content"><div class="state-symbol">${icon('"'wait')}</div><div class=\"page-intro\"><h1 tabindex=\"-1\">Waiting for Priya</h1><p>Your handover request is pending acceptance.</p></div>"'${transfer()}<aside class="notice pending-responsibility"><b>You’re still on call</b><p>You remain responsible for ${M.rotation} until Priya accepts.</p></aside><div class="actions">${button('"'Back to schedule','schedule')}"'${button('"'Cancel request','cancel-request','text-button')}</div></div>"'${footer()}`;
  }
  function acceptedView() {
    return `${header()}<div class="content"><div class="state-symbol success">${icon('"'check')}</div><div class=\"page-intro\"><div class=\"eyebrow\">Handover complete</div><h1 tabindex=\"-1\">Priya is now on call</h1><p>You’re off call for the rest of this shift.</p></div>"'${transfer()}<p class="responsibility">${icon('"'check')}<span>Priya accepted responsibility for "'${M.rotation} until ${M.shiftEnd} UTC.</span></p><div class="actions">${button('"'Back to schedule','schedule')}</div></div>"'${footer()}`;
  }
  function emptyView() {
    return `${header()}<div class="content empty-content"><div class="state-symbol">${icon('"'calendar')}</div><h1 tabindex=\"-1\">No schedule available</h1><p>There are no on-call shifts to show. Check with your rotation owner to confirm coverage.</p><div class=\"actions\">"'${button('"'Check again','check-empty','secondary')}</div><p class=\"screen-status\" role=\"status\" id=\"empty-status\"></p></div>"'${footer()}`;
  }
  function writeURL(replace=false) {
    const url = new URL(location.href);
    url.searchParams.set('"'screen',screen);
    if(owner==='priya') url.searchParams.set('owner','priya'); else url.searchParams.delete('owner');
    if(pending) url.searchParams.set('request','pending'); else url.searchParams.delete('request');
    history[replace?'replaceState':'pushState']({},'',url);
  }
  function render(focus=false) {
    app.className = screen === 'offline' ? 'offline' : '';
    app.innerHTML = screen==='main'? mainView() : screen==='offline'? mainView(true) : screen==='compose'? composeView() : screen==='review'? reviewView() : screen==='pending'? pendingView() : screen==='accepted'? acceptedView() : emptyView();
    document.title = "'`Rota — ${ {main:'"'On call',compose:'Hand over shift',review:'Review handover',pending:'Waiting for Priya',offline:'Offline schedule',empty:'No schedule',accepted:'Handover complete'}[screen]}"'`;
    app.scrollTop = 0;
    if(focus) app.querySelector('"'h1')?.focus({preventScroll:true});
  }
  function go(next) { screen=next; flash=''; writeURL(); render(true); }
  function cancelRequest() { pending=false; screen='main'; flash='Request cancelled. You’re still on call.'; writeURL(); render(true); }
  app.addEventListener('input',e=>{if(e.target.id==='note') note=e.target.value;});
  app.addEventListener('change',e=>{if(e.target.name==='recipient'){selected=true;app.querySelector('#review-button').disabled=false;}});
  app.addEventListener('submit',e=>{e.preventDefault();if(selected){note=app.querySelector('#note').value;go('review');}});
  app.addEventListener('click',e=>{
    const action=e.target.closest('[data-action]')?.dataset.action;
    if("'!action) return;
    if(action==='"'compose'){if(screen==='review') selected=true;go('compose');}
    if(action==='pending') go('pending');
    if(action==='cancel'){selected=false;note='';go('main');}
    if(action==='send'){pending=true;go('pending');}
    if(action==='schedule') go('main');
    if(action==='cancel-request') cancelRequest();
    if(action==='retry') app.querySelector('#retry-status').textContent='Still offline. The last-known schedule is shown.';
    if(action==='check-empty') app.querySelector('#empty-status').textContent='No schedule is available. Confirm coverage with your rotation owner.';
  });
  document.addEventListener('keydown',e=>{
    if(e.key==='Escape' && ['compose','review'].includes(screen)){e.preventDefault();if(screen==='review')go('compose');else go('main');}
  });
  window.addEventListener('popstate',()=>{
    const q=new URLSearchParams(location.search);screen=states.includes(q.get('screen'))?q.get('screen'):'main';owner=q.get('owner')==='priya'||screen==='accepted'?'priya':'jamie';pending=screen==='pending'||q.get('request')==='pending';render(true);
  });
