  window.addEventListener('message',e=>{
    if(window.parent===window || e.source"'!==window.parent || e.data?.type!=='"'rota:simulate-acceptance' || "'!pending) return;
    pending=false;owner='"'priya';go('accepted');
  });
  render();
})();
